pub fn host_skill_limits(name: &str, behavior: HostBehavior) -> crate::catalog::SkillLimits {
    match behavior {
        HostBehavior::Real => crate::catalog::SkillLimits { once_per_turn: true },
        _ => crate::catalog::SkillLimits::default(),
    }
}
